import React from 'react';
import SunsetPredictor from './sunsetPredictor';
import './App.css';

function App() {
  return (
    <div className="app">
      <SunsetPredictor />
      <footer className="app-footer">
        <p>SunPredictor</p>
        <p className="footer-note">Weather via Open-Meteo · Scored with gradient boosting</p>
      </footer>
    </div>
  );
}

export default App;
